import { createRequire } from "node:module"
import { writeFileSync } from "node:fs"

const require = createRequire("/Users/inducingchaos/Workspace/containers/altered/packages/server-experimental/package.json")
const { Client } = require("pg")

const client = new Client({ connectionString: process.env.DB_URL })
await client.connect()

const limit = Number(process.argv[2] ?? 200)
const offset = Number(process.argv[3] ?? 0)

const res = await client.query(
    `select id, conversation_id, role, content, created_at
     from chat_messages
     where user_id is null
     order by created_at desc
     limit $1 offset $2`,
    [limit, offset]
)

const lines = res.rows.map(r => {
    const content = typeof r.content === "string" ? r.content : JSON.stringify(r.content)
    return `=== [${r.created_at.toISOString()}] ${r.role} (conv ${String(r.conversation_id).slice(0, 8)}) ===\n${content}\n`
})

writeFileSync(`/tmp/koa-messages-${offset}.txt`, lines.join("\n"))
console.log(`wrote ${res.rows.length} messages to /tmp/koa-messages-${offset}.txt`)

await client.end()
